n dust (remaining token balance) is transferred to the position owner"},"EnterLeverageForwarded(address,address,uint256,uint256)":{"notice":"Emitted when enterLeverage is forwarded to the LeverageManager"},"ExitLeverageForwarded(address,address,uint256,uint256)":{"notice":"Emitted when exitLeverage is forwarded to the LeverageManager"},"ExitSingleAssetLeverageForwarded(address,uint256)":{"notice":"Emitted when exitSingleAssetLeverage is forwarded to the LeverageManager"},"GenericCallExecuted(address,bytes)":{"notice":"Emitted when a generic call is executed"},"MarketExited(address)":{"notice":"Emitted when a market is exited via the Comptroller"}},"kind":"user","methods":{"COMPTROLLER()":{"notice":"Address of the Venus Comptroller (same for all clones)"},"LEVERAGE_MANAGER()":{"notice":"Address of the LeverageStrategiesManager contract (same for all clones)"},"RELATIVE_POSITION_MANAGER()":{"notice":"Address of the authorized RelativePositionManager contract (same for all clones)"},"constructor":{"notice":"Constructor for the PositionAccount implementation contract"},"enterLeverage(address,uint256,address,uint256,uint256,bytes)":{"notice":"Forwards enterLeverage to the LeverageStrategiesManager on behalf of this position account"},"exitLeverage(address,uint256,address,uint256,uint256,bytes)":{"notice":"Forwards exitLeverage to the LeverageStrategiesManager on behalf of this position account"},"exitMarket(address)":{"notice":"Exits a market by calling comptroller.exitMarket with this position account as the sender"},"exitSingleAssetLeverage(address,uint256)":{"notice":"Forwards exitSingleAssetLeverage to the LeverageStrategiesManager on behalf of this position account"},"genericCalls(address[],bytes[])":{"notice":"Executes multiple generic calls to external contracts"},"initialize(address,address,address)":{"notice":"Initializes a new position account clone"},"longVToken()":{"notice":"Address of the long vToken for this position"},"owner()":{"notice":"Address of the po